// Accedemos a los datos que vienen del webhook
// Según la imagen, el payload está en: $input.first().json.body
const webhookPayload = $input.first().json.body;

// El texto que necesitamos está en el campo 'chatInput' dentro del body
const escapedLogText = webhookPayload?.chatInput;

// Verificamos si obtuvimos el texto. Si no, no hay nada que procesar.
if (!escapedLogText) {
    console.log("escapedLogText está vacío o nulo. No hay texto para procesar.");
    return [{ json: { error: "escapedLogText está vacío o nulo." } }]; // Devolver algo para indicar el error
}

// Desescapamos los saltos de línea: reemplazamos '\\n' por '\n' reales
const logText = escapedLogText.replace(/\\n/g, '\n');

// --- Inicio de la CORRECCIÓN ---
// Regex para identificar la línea completa que inicia una oportunidad
const opportunityHeaderString = "\\d{4}-\\d{2}-\\d{2} \\d{2}:\\d{2}:\\d{2},\\d{3} - \\S+ - \\S+ - Oportunidad encontrada";

// Regex para capturar bloques completos, cada uno comenzando con el opportunityHeaderString
// y extendiéndose hasta el siguiente opportunityHeaderString o el final del texto.
// Usamos el flag 'g' (global) y 's' (dotall, para que '.' coincida con saltos de línea).
const blocksRegex = new RegExp(`(${opportunityHeaderString})(.*?)(?=${opportunityHeaderString}|$)`, "gs");

const opportunityBlocks = [];
let match;
while ((match = blocksRegex.exec(logText)) !== null) {
    // match[0] es el bloque completo incluyendo el header del siguiente (si no es el final)
    // match[1] es el header de la oportunidad actual
    // match[2] es el cuerpo de la oportunidad actual
    // Para reconstruir el bloque correctamente tal como lo procesaba el resto del código:
    // combinamos el header de la oportunidad actual (match[1]) con su cuerpo (match[2])
    opportunityBlocks.push(match[1] + match[2]);
}
// --- Fin de la CORRECCIÓN ---

const processedOpportunities = [];

if (opportunityBlocks && opportunityBlocks.length > 0) { // Modificada la condición para ser más explícita
    for (const block of opportunityBlocks) {
        const opportunityData = {};

        // Extraer el ID (fecha y hora) y añadir 'n'
        // Ahora 'block' SÍ comienza con el timestamp.
        const idMatch = block.match(/^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3})/);
        if (idMatch && idMatch[1]) {
            opportunityData.id = 'n' + idMatch[1];
        } else {
            // Este caso debería ser menos probable ahora si los bloques se forman correctamente
            console.warn("Bloque no comienza con timestamp esperado:", block.substring(0, 80) + "...");
            opportunityData.id = 'timestamp_missing_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5); // ID temporal más único
        }

        // Extraer la línea completa de 'Oportunidad encontrada' y el ciclo (A->C->B->A)
        // Esta regex sigue siendo válida ya que busca dentro del 'block'
        const oportunidadMatch = block.match(/Oportunidad encontrada (.*?): (.*?)\n/);
        if (oportunidadMatch) {
            opportunityData.ciclo = oportunidadMatch[1]?.trim() || '';
            opportunityData.oportunidad = oportunidadMatch[2]?.trim() || '';
            opportunityData.oportunidadCompleta = oportunidadMatch[0]?.trim() || '';
        }

        const paresMatch = block.match(/Pares: (.*?)\n/);
        if (paresMatch && paresMatch[1]) {
            const paresString = paresMatch[1].trim();
            opportunityData.pares = paresString.split(', ');
        }

        const preciosMatch = block.match(/Precios: (.*?)\n/);
        if (preciosMatch && preciosMatch[1]) {
            opportunityData.precios = preciosMatch[1].trim();
        }

        const factoresMatch = block.match(/Factores: (.*?)\n/);
        if (factoresMatch && factoresMatch[1]) {
            opportunityData.factores = factoresMatch[1].trim();
        }

        const rentabilidadMatch = block.match(/Rentabilidad Bruta: (.*?)\n/);
        if (rentabilidadMatch && rentabilidadMatch[1]) {
            opportunityData.rentabilidadBruta = rentabilidadMatch[1].trim();
        }

        const sendingMatch = block.match(/Enviando oportunidad a webhook: (.*?)\n/);
        if (sendingMatch && sendingMatch[1]) {
            opportunityData.webhookDestino = sendingMatch[1].trim();
        }

        // Ajuste en errorMatch para asegurar que no se solape con el inicio de un nuevo bloque si está mal delimitado
        const errorMatch = block.match(/ERROR - (.*?)(?=\n\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2},\d{3} - \S+ - \S+ - (?:Oportunidad encontrada|ERROR -)|$)/s);
        if (errorMatch && errorMatch[0]) { // Usar errorMatch[0] para capturar "ERROR - " también
            opportunityData.error = errorMatch[0].trim();
        }

        if (opportunityData.id && !opportunityData.id.startsWith('timestamp_missing_')) { // Dar prioridad a IDs bien formados
            processedOpportunities.push({ json: opportunityData });
        } else if (opportunityData.oportunidadCompleta) { // Si el ID falló pero hay datos de oportunidad
            console.warn("Oportunidad procesada con ID faltante/temporal:", opportunityData.id);
            processedOpportunities.push({ json: opportunityData });
        } else {
            console.warn("Bloque no procesado (sin ID válido ni oportunidad principal):", block.substring(0, 80) + "...");
        }
    }
} else {
    console.warn("No se encontraron bloques de oportunidad en el texto proporcionado con la nueva regex.");
    // Devolver el log original o un mensaje de error si no se encuentran bloques
    if (logText && logText.length > 0 && !processedOpportunities.length) {
        return [{ json: { info: "No se encontraron bloques de oportunidad procesables.", original_log_excerpt: logText.substring(0, 200) } }];
    }
}

if (processedOpportunities.length === 0 && logText && logText.includes("Oportunidad encontrada")) {
    // Si esperábamos oportunidades pero no obtuvimos ninguna, es una señal de que la regex principal falló.
    console.error("Se detectó 'Oportunidad encontrada' en el log, pero la regex de bloques no produjo resultados. Revisar `blocksRegex`.");
    return [{ json: { critical_error: "Regex de parseo de bloques falló a pesar de existir datos.", log_sample: logText.substring(0,500) } }];
}


return processedOpportunities;

// ------------------------------------------------------------------------------------
// La respuesta del AgenteIA está en $input.first().json.output según tu indicación.
// ------------------------------------------------------------------------------------
const aiFullResponse = $input.first().json.output;

let jsonToParse = "";

// 1. Verificar si la respuesta es una cadena de texto
if (typeof aiFullResponse !== 'string') {
  console.error("Entrada 'aiFullResponse' NO ES TEXTO. Valor recibido de $input.first().json.output:", aiFullResponse);
  return {
    output: {
      recomendacion: 'DESCARTAR',
      confianza: 0,
      rentabilidad_neta_estimada: 0.0,
      riesgos_identificados: ["Error: La entrada ($input.first().json.output) no es texto."],
      explicacion: "El formato de la respuesta del Agente IA no pudo ser leído (tipo de dato incorrecto)."
    }
  };
}

// 2. Intentar extraer el contenido JSON usando una expresión regular
const jsonBlockMatch = aiFullResponse.match(/```json\s*([\s\S]*?)\s*```/);

if (jsonBlockMatch && jsonBlockMatch[1]) {
  jsonToParse = jsonBlockMatch[1].trim();
} else {
  console.warn("Bloque ```json ... ``` no encontrado en la respuesta. Se intentará parsear la respuesta completa directamente.");
  jsonToParse = aiFullResponse.trim();
}

// console.log("Cadena JSON extraída para parsear:", jsonToParse);

// 3. Verificar si la cadena extraída parece un objeto JSON (básico)
if (!jsonToParse || !jsonToParse.startsWith("{") || !jsonToParse.endsWith("}")) {
    console.error("La cadena extraída ('jsonToParse') no parece ser un objeto JSON válido. Valor:", jsonToParse.substring(0,200)+"...");
    return {
        output: {
          recomendacion: 'DESCARTAR',
          confianza: 0,
          rentabilidad_neta_estimada: 0.0,
          riesgos_identificados: ["Error: El contenido extraído de la IA no tiene formato JSON (no está entre '{...}')."],
          explicacion: `La estructura de la respuesta del Agente IA no es la esperada. Extracto procesado: ${String(jsonToParse).substring(0, 100)}...`
        }
      };
}

// ---------- INICIO DE LA MODIFICACIÓN PARA ESCAPAR MARKDOWNV2 ----------
// Función para escapar caracteres especiales de MarkdownV2
function escapeMarkdownV2(text) {
  if (typeof text !== 'string') {
    return text; // Devuelve el original si no es string
  }
  // Caracteres a escapar en MarkdownV2. La barra invertida \ debe ser la primera en escaparse.
  // Luego otros caracteres que son parte de la sintaxis Markdown.
  const escapeChars = /[\\_*[\]()~`>#+\-=|{}.!]/g; // Añadido \ y . !
  return text.replace(escapeChars, '\\$&');     // '$&' significa la cadena completa que coincidió
}
// ---------- FIN DE LA MODIFICACIÓN PARA ESCAPAR MARKDOWNV2 ----------

// 4. Intentar parsear la cadena JSON y estructurar la salida para Telegram
try {
  const parsedAIResponse = JSON.parse(jsonToParse);

  const outputData = {
    recomendacion: parsedAIResponse.recomendacion || 'DESCARTAR',
    confianza: typeof parsedAIResponse.confianza === 'number' ? parsedAIResponse.confianza : 0,
    rentabilidad_neta_estimada: typeof parsedAIResponse.rentabilidad_neta_estimada === 'number' ? parsedAIResponse.rentabilidad_neta_estimada : 0.0,
    // Inicializar riesgos_identificados y explicacion para poder aplicar escapeMarkdownV2
    riesgos_identificados: [], 
    explicacion: parsedAIResponse.explicacion || "No se proporcionó explicación detallada en el JSON."
  };

  // ---------- INICIO DE LA APLICACIÓN DEL ESCAPADO ----------
  // Escapar el contenido de 'explicacion' para MarkdownV2
  outputData.explicacion = escapeMarkdownV2(outputData.explicacion);

  // Escapar cada elemento en 'riesgos_identificados' para MarkdownV2
  if (Array.isArray(parsedAIResponse.riesgos_identificados) && parsedAIResponse.riesgos_identificados.length > 0) {
    outputData.riesgos_identificados = parsedAIResponse.riesgos_identificados.map(riesgo => escapeMarkdownV2(String(riesgo))); // Asegurar que riesgo sea string
  } else {
    // Si no hay riesgos o no es un array, usar un valor por defecto (ya es texto plano, no necesita escape general aquí)
    outputData.riesgos_identificados = ["No se especificaron riesgos en el JSON."]; 
  }
  // ---------- FIN DE LA APLICACIÓN DEL ESCAPADO ----------

  return { output: outputData };

} catch (error) {
  console.error("Error al parsear JSON desde la respuesta del AgenteIA:", error);
  console.error("Cadena JSON problemática que falló el parseo:", jsonToParse.substring(0, 500) + "...");

  return {
    output: {
      recomendacion: 'DESCARTAR',
      confianza: 0,
      rentabilidad_neta_estimada: 0.0,
      riesgos_identificados: ["Error crítico al interpretar el JSON del AI.", `Detalle del error: ${error.message}`],
      explicacion: `La respuesta del Agente IA no pudo ser convertida a JSON válido. Extracto problemático: ${jsonToParse.substring(0, 100)}...`
    }
  };
}
